(() => {
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const state={token:localStorage.getItem('fenix_token')||'',me:null,chats:[],chat:null,messages:[],section:'chats',settings:null,theme:localStorage.getItem('fenix_theme')||'light',authMode:'login',authStep:'email',email:'',signupToken:'',search:'',ws:null,editing:null,reply:null};
  const api=async(path,opt={})=>{const h={'Content-Type':'application/json',...(opt.headers||{})}; if(state.token)h.Authorization=`Bearer ${state.token}`; const r=await fetch('/api'+path,{...opt,headers:h}); let d={}; try{d=await r.json()}catch{} if(!r.ok){if(r.status===401){localStorage.removeItem('fenix_token');state.token='';state.me=null;renderAuth();} throw new Error(d.detail||'Ошибка сервера')} return d};
  const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const avatar=(u,size='md')=>u?.avatar?`<img class="avatar ${size}" src="${esc(u.avatar)}" onerror="this.style.display='none'">`:`<div class="avatar ${size}">${esc((u?.display_name||u?.title||u?.username||'?').slice(0,1).toUpperCase())}</div>`;
  const toast=t=>{let x=$('.toast');if(!x){x=document.createElement('div');x.className='toast';document.body.append(x)}x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2600)};
  function render(){document.body.dataset.theme=state.theme;if(!state.token){renderAuth();return}renderApp()}
  function renderAuth(){document.body.innerHTML=`<div class="auth-page"><div class="auth-card"><div class="brand">✈️ <b>Fenix</b></div><div class="auth-sub">Мессенджер нового поколения</div><div id="auth-body"></div></div></div>`; renderAuthBody()}
  function renderAuthBody(){const b=$('#auth-body'); if(state.authStep==='email') b.innerHTML=`<h1>${state.authMode==='register'?'Создать аккаунт':'Войти'}</h1><p class="muted">${state.authMode==='register'?'Введите email — на него придёт код подтверждения.':'Введите email вашего аккаунта.'}</p><label>Email</label><input id="email" type="email" autocomplete="email" placeholder="you@example.com" value="${esc(state.email)}"><button class="primary wide" id="email-go">Продолжить</button><div class="auth-switch">${state.authMode==='register'?'Уже есть аккаунт?':'Нет аккаунта?'} <button class="link" id="switch-auth">${state.authMode==='register'?'Войти':'Зарегистрироваться'}</button></div>`;
    else if(state.authStep==='code') b.innerHTML=`<button class="back" id="auth-back">‹</button><h1>Введите код</h1><p class="muted">Код отправлен на <b>${esc(state.email)}</b></p><input id="code" class="code" inputmode="numeric" maxlength="6" placeholder="000000"><button class="primary wide" id="code-go">Подтвердить</button><button class="link resend" id="resend">Отправить код снова</button>`;
    else b.innerHTML=`<button class="back" id="profile-back">‹</button><h1>Ваш профиль</h1><p class="muted">Остался последний шаг.</p><div class="profile-avatar" id="avatar-pick">${avatar({display_name:'?'},'xl')}</div><input id="avatar" placeholder="Ссылка на аватар (необязательно)"><label>Имя</label><input id="display" maxlength="80" placeholder="Ваше имя"><label>Username</label><div class="username"><span>@</span><input id="username" minlength="5" maxlength="32" placeholder="minimum 5 symbols"></div><small class="muted">От 5 символов: латиница, цифры и _</small><button class="primary wide" id="profile-go">Готово</button>`;
    bindAuth(); }
  function bindAuth(){ $('#switch-auth')?.addEventListener('click',()=>{state.authMode=state.authMode==='register'?'login':'register';renderAuthBody()}); $('#auth-back')?.addEventListener('click',()=>{state.authStep='email';renderAuthBody()}); $('#profile-back')?.addEventListener('click',()=>{state.authStep='code';renderAuthBody()}); $('#email-go')?.addEventListener('click',requestCode); $('#resend')?.addEventListener('click',requestCode); $('#code-go')?.addEventListener('click',verifyCode); $('#profile-go')?.addEventListener('click',completeProfile); $('#code')?.addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,6)}); }
  async function requestCode(){const email=$('#email')?.value.trim().toLowerCase()||state.email;if(!/^\S+@\S+\.\S+$/.test(email))return toast('Введите корректный email');state.email=email;try{await api('/auth/email/request',{method:'POST',body:JSON.stringify({email,purpose:state.authMode==='register'?'register':'login'})});state.authStep='code';renderAuthBody();toast('Код отправлен на почту')}catch(e){toast(e.message)}}
  async function verifyCode(){const code=$('#code')?.value.trim();if(code.length!==6)return toast('Введите 6-значный код');try{const d=await api('/auth/email/verify',{method:'POST',body:JSON.stringify({email:state.email,code,purpose:state.authMode==='register'?'register':'login'})});if(d.status==='authenticated'){state.token=d.access_token;localStorage.setItem('fenix_token',state.token);await boot()}else{state.signupToken=d.signup_token;state.authStep='profile';renderAuthBody()}}catch(e){toast(e.message)}}
  async function completeProfile(){const display=$('#display')?.value.trim(),username=$('#username')?.value.trim(),avatarUrl=$('#avatar')?.value.trim();if(!display||username.length<5)return toast('Заполните имя и username от 5 символов');try{const d=await api('/auth/email/complete?signup_token='+encodeURIComponent(state.signupToken),{method:'POST',body:JSON.stringify({username,display_name:display,avatar:avatarUrl||null})});state.token=d.access_token;localStorage.setItem('fenix_token',state.token);await boot()}catch(e){toast(e.message)}}
  async function boot(){try{state.me=await api('/auth/me');state.chats=await api('/chats');state.settings=await api('/social/settings');state.theme=state.settings.theme||state.theme;render()}catch(e){localStorage.removeItem('fenix_token');state.token='';renderAuth();toast(e.message)}}
  function renderApp(){document.body.innerHTML=`<div class="app"><aside class="sidebar"><div class="side-top"><button class="icon-btn" id="menu">☰</button><div class="search"><span>⌕</span><input id="global-search" placeholder="Поиск" value="${esc(state.search)}"></div></div><div class="folders"><button class="folder active" data-section="chats">Все</button><button class="folder" data-section="unread">Непрочитанные</button><button class="folder" data-section="groups">Группы</button><button class="folder" data-section="channels">Каналы</button><button class="folder" data-section="saved">Избранное</button></div><div id="chat-list" class="chat-list"></div><div class="profile-mini" id="profile-open">${avatar(state.me)}<div><b>${esc(state.me?.display_name)}</b><small>@${esc(state.me?.username)}</small></div><button class="dots">⋮</button></div></aside><main class="chat-area"><div id="chat-content"></div></main><div id="drawer"></div></div>`;bindApp();renderChatList();renderChat();}
  function bindApp(){$('#menu').onclick=()=>openDrawer('menu');$('#profile-open').onclick=()=>openDrawer('profile');$('#global-search').oninput=e=>{state.search=e.target.value;renderChatList()};$$('.folder').forEach(b=>b.onclick=()=>{state.section=b.dataset.section;$$('.folder').forEach(x=>x.classList.toggle('active',x===b));renderChatList()})}
  function filteredChats(){let a=[...state.chats];if(state.section==='groups')a=a.filter(x=>x.kind==='group');if(state.section==='channels')a=a.filter(x=>x.kind==='channel');if(state.section==='saved')a=a.filter(x=>x.kind==='saved');if(state.search){const q=state.search.toLowerCase();a=a.filter(x=>(x.title||'').toLowerCase().includes(q)||(x.username||'').toLowerCase().includes(q))}return a}
  function renderChatList(){const el=$('#chat-list');if(!el)return;const a=filteredChats();el.innerHTML=a.length?a.map(c=>`<button class="chat-row ${state.chat?.id===c.id?'selected':''}" data-id="${c.id}">${avatar(c)}<span class="chat-meta"><b>${esc(c.title)}</b><small>${esc(c.kind==='channel'?'Канал':c.username?'@'+c.username:'Нажмите, чтобы открыть чат')}</small></span><span class="chat-time">${c.kind==='saved'?'⭐':''}</span></button>`).join(''):`<div class="empty-list"><div>⌕</div><b>Ничего не найдено</b><small>Попробуйте изменить запрос</small></div>`;$$('.chat-row').forEach(x=>x.onclick=()=>openChat(Number(x.dataset.id)))}
  async function openChat(id){try{state.chat=state.chats.find(x=>x.id===id)||null;state.messages=await api(`/chats/${id}/messages?limit=200`);renderChatList();renderChat();connectWS()}catch(e){toast(e.message)}}
  function renderChat(){const el=$('#chat-content');if(!el)return;if(!state.chat){el.innerHTML=`<div class="welcome"><div class="welcome-logo">✈</div><h2>Fenix Messenger</h2><p>Выберите чат, чтобы начать общение</p><small>Ваши сообщения защищены и синхронизируются в реальном времени</small></div>`;return}const c=state.chat;el.innerHTML=`<header class="chat-header"><button class="back-mobile" id="back-list">‹</button>${avatar(c)}<div class="head-info"><b>${esc(c.title)}</b><small>${c.kind==='private'?'в сети':c.kind==='group'?'участники группы':'канал'}</small></div><div class="head-actions"><button class="icon-btn" id="chat-search">⌕</button><button class="icon-btn" id="call">☎</button><button class="icon-btn" id="chat-menu">⋮</button></div></header><div class="pinned">📌 <span>Закреплённые сообщения</span></div><section class="messages" id="messages">${state.messages.map(messageHTML).join('')}</section><div class="composer-wrap"><div id="replybar"></div><div class="composer"><button class="icon-btn" id="attach">📎</button><textarea id="message-input" rows="1" placeholder="Сообщение" spellcheck="true"></textarea><button class="icon-btn" id="emoji">☺</button><button class="send-btn" id="send">➤</button></div></div>`;bindChat();scrollBottom();}
  function messageHTML(m){const mine=m.sender_id===state.me?.id;return `<article class="message ${mine?'mine':''} ${m.pinned?'is-pinned':''}" data-id="${m.id}"><div class="bubble">${!mine?`<b class="sender">${esc(m.sender_name||'Пользователь')}</b>`:''}${m.reply_to?`<div class="reply">↪ Ответ на сообщение</div>`:''}<div class="text">${m.deleted?'Сообщение удалено':esc(m.text||'')}</div>${m.media_url?`<a class="media" href="${esc(m.media_url)}" target="_blank">📎 Вложение</a>`:''}<div class="meta">${m.edited?'изменено · ':''}${new Date(m.created_at||Date.now()).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})} ${mine?'✓✓':''}</div></div><button class="msg-more">⋮</button></article>`}
  function bindChat(){$('#send').onclick=sendMessage;$('#message-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}};$('#message-input').oninput=e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,150)+'px';sendTyping()};$('#emoji').onclick=()=>openEmoji();$('#attach').onclick=()=>openDrawer('attach');$('#chat-menu').onclick=()=>openDrawer('chat');$('#chat-search').onclick=()=>toast('Поиск по чату: введите запрос в верхнем поле');$('#call').onclick=()=>toast('Звонки доступны через WebRTC-модуль');$$('.msg-more').forEach(x=>x.onclick=e=>openMessageMenu(Number(x.closest('.message').dataset.id),e.currentTarget));$('#back-list').onclick=()=>document.body.classList.remove('mobile-chat')}
  async function sendMessage(){const i=$('#message-input');const text=i?.value.trim();if(!text||!state.chat)return;try{const m=await api(`/chats/${state.chat.id}/messages`,{method:'POST',body:JSON.stringify({text,reply_to_id:state.reply?.id||null})});state.messages.push(m);state.reply=null;i.value='';renderChat()}catch(e){toast(e.message)}}
  let typingTimer;function sendTyping(){if(!state.ws||state.ws.readyState!==1)return;clearTimeout(typingTimer);state.ws.send(JSON.stringify({type:'typing'}));typingTimer=setTimeout(()=>{},1200)}
  function connectWS(){if(state.ws)try{state.ws.close()}catch{};if(!state.chat||!state.token)return;const proto=location.protocol==='https:'?'wss':'ws';state.ws=new WebSocket(`${proto}://${location.host}/ws/${state.chat.id}?token=${encodeURIComponent(state.token)}`);state.ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.type==='message'&&d.message?.chat_id===state.chat.id){if(!state.messages.some(x=>x.id===d.message.id)){state.messages.push(d.message);renderChat()}}if(d.type==='message_deleted'){state.messages=state.messages.map(x=>x.id===d.message_id?{...x,deleted:true,text:''}:x);renderChat()}}}
  function scrollBottom(){setTimeout(()=>{const m=$('#messages');if(m)m.scrollTop=m.scrollHeight},0)}
  function openEmoji(){const emojis='😀 😃 😄 😂 🤣 😊 😍 🥰 😎 🤩 🥳 😏 😢 😭 😡 🤬 🤯 😱 🤔 🤗 😴 🤤 🤑 👍 👎 👌 ✌️ 🤝 🙏 ❤️ 🧡 💛 💚 💙 💜 🖤 🤍 🔥 ⭐ 🎉 🚀 💯'.split(' ');openDrawer('emoji',emojis)}
  function openMessageMenu(id){const m=state.messages.find(x=>x.id===id),mine=m?.sender_id===state.me?.id;openDrawer('message',{id,mine})}
  function openDrawer(type,data){const d=$('#drawer');if(!d)return;let html='';if(type==='menu')html=`<div class="drawer"><div class="drawer-head">${avatar(state.me)}<div><b>${esc(state.me.display_name)}</b><small>@${esc(state.me.username)}</small></div><button id="drawer-close">×</button></div><button class="drawer-item" data-action="profile">👤 Профиль</button><button class="drawer-item" data-action="contacts">👥 Контакты</button><button class="drawer-item" data-action="saved">⭐ Избранное</button><button class="drawer-item" data-action="calls">📞 Звонки</button><button class="drawer-item" data-action="settings">⚙️ Настройки</button><button class="drawer-item" data-action="appearance">🎨 Оформление</button><button class="drawer-item" data-action="devices">💻 Устройства</button><button class="drawer-item danger" data-action="logout">↪ Выйти</button></div>`;
    if(type==='profile')html=`<div class="modal"><div class="modal-head"><h2>Профиль</h2><button id="drawer-close">×</button></div><div class="profile-big">${avatar(state.me,'xxl')}</div><h2>${esc(state.me.display_name)}</h2><div class="username-line">@${esc(state.me.username)}</div><div class="profile-grid"><div><small>ID</small><b>${esc(state.me.public_code||state.me.id)}</b></div><div><small>Email</small><b>${esc(state.me.email||'—')}</b></div></div><p>${esc(state.me.bio||'Добавьте описание в настройках')}</p><button class="primary wide" data-action="edit-profile">Изменить профиль</button></div>`;
    if(type==='attach')html=`<div class="sheet"><div class="sheet-title">Вложение</div><div class="attach-grid"><button>🖼️<span>Фото</span></button><button>🎥<span>Видео</span></button><button>📎<span>Документ</span></button><button>🎵<span>Музыка</span></button><button>🎤<span>Голосовое</span></button><button>📍<span>Геопозиция</span></button><button>📊<span>Опрос</span></button><button>👤<span>Контакт</span></button></div><button id="drawer-close" class="sheet-cancel">Отмена</button></div>`;
    if(type==='chat')html=`<div class="sheet"><div class="sheet-title">${esc(state.chat?.title||'Чат')}</div><button class="sheet-item">🔎 Поиск</button><button class="sheet-item">📌 Закреплённые</button><button class="sheet-item">🔔 Уведомления</button><button class="sheet-item">🖼️ Медиа, файлы и ссылки</button><button class="sheet-item">👥 Участники</button><button class="sheet-item">🔗 Ссылка на чат</button><button class="sheet-item danger">🗑️ Очистить историю</button><button id="drawer-close" class="sheet-cancel">Отмена</button></div>`;
    if(type==='emoji')html=`<div class="emoji-sheet"><div class="emoji-tabs">😀　🧸　GIF</div><div class="emoji-grid">${data.map(e=>`<button>${e}</button>`).join('')}</div><button id="drawer-close" class="sheet-cancel">Закрыть</button></div>`;
    if(type==='message')html=`<div class="sheet"><div class="sheet-title">Сообщение</div><button class="sheet-item" data-action="reply" data-id="${data.id}">↩ Ответить</button><button class="sheet-item" data-action="favorite" data-id="${data.id}">⭐ В избранное</button><button class="sheet-item" data-action="pin" data-id="${data.id}">📌 Закрепить</button><button class="sheet-item" data-action="reaction" data-id="${data.id}">❤️ Реакция</button>${data.mine?'<button class="sheet-item" data-action="edit" data-id="'+data.id+'">✏️ Изменить</button><button class="sheet-item danger" data-action="delete" data-id="'+data.id+'">🗑️ Удалить</button>':''}<button id="drawer-close" class="sheet-cancel">Отмена</button></div>`;
    if(type==='settings')html=settingsModal();
    if(type==='contacts')html=contactsModal();
    if(type==='appearance')html=appearanceModal();
    if(type==='devices')html=`<div class="modal"><div class="modal-head"><h2>Устройства</h2><button id="drawer-close">×</button></div><div class="device"><span>💻</span><div><b>Текущее устройство</b><small>${navigator.userAgent.includes('Mobile')?'Телефон':'Браузер'} · ${location.hostname}</small></div><i>Активно</i></div><button class="danger-btn wide">Завершить другие сеансы</button></div>`;
    if(type==='calls')html=`<div class="modal"><div class="modal-head"><h2>Звонки</h2><button id="drawer-close">×</button></div><div class="big-empty">📞<b>Звонков пока нет</b><small>Начните звонок из профиля пользователя.</small></div></div>`;
    d.innerHTML=`<div class="overlay"></div>${html}`;d.classList.add('open');$('.overlay',d).onclick=closeDrawer;$('#drawer-close',d)?.addEventListener('click',closeDrawer);$$('[data-action]',d).forEach(x=>x.onclick=()=>handleAction(x.dataset.action,x.dataset.id));$$('.emoji-grid button',d).forEach(x=>x.onclick=()=>{const i=$('#message-input');if(i){i.value+=x.textContent;i.focus()}closeDrawer()});}
  function closeDrawer(){$('#drawer')?.classList.remove('open')}
  function settingsModal(){return `<div class="modal"><div class="modal-head"><h2>Настройки</h2><button id="drawer-close">×</button></div><div class="settings-user">${avatar(state.me)}<div><b>${esc(state.me.display_name)}</b><small>@${esc(state.me.username)}</small></div></div><h3>Аккаунт</h3><button class="setting-row" data-action="edit-profile"><span>👤</span><div>Профиль<small>Имя, аватар, username, описание</small></div><b>›</b></button><h3>Настройки</h3><button class="setting-row" data-action="toggle-theme"><span>🌙</span><div>Тёмная тема<small>${state.theme==='dark'?'Включена':'Выключена'}</small></div><b>›</b></button><button class="setting-row"><span>🔔</span><div>Уведомления<small>Сообщения и звонки</small></div><b>›</b></button><button class="setting-row"><span>🔒</span><div>Конфиденциальность<small>Кто может писать и видеть данные</small></div><b>›</b></button><button class="setting-row"><span>🔐</span><div>Безопасность<small>2FA и активные сеансы</small></div><b>›</b></button><h3>Приложение</h3><button class="setting-row"><span>💾</span><div>Данные и хранилище<small>Кэш, загрузки, автозагрузка</small></div><b>›</b></button><button class="setting-row"><span>🌐</span><div>Язык<small>Русский</small></div><b>›</b></button></div>`}
  function contactsModal(){return `<div class="modal wide-modal"><div class="modal-head"><h2>Контакты</h2><button id="drawer-close">×</button></div><div class="contact-search"><input id="people-q" placeholder="Имя, @username или 3/4-значный ID"><button id="people-go">⌕</button></div><div id="people-list" class="people-list"><div class="muted center">Введите минимум 2 символа для поиска</div></div></div>`}
  function appearanceModal(){return `<div class="modal"><div class="modal-head"><h2>Оформление</h2><button id="drawer-close">×</button></div><div class="theme-cards"><button data-theme="light" class="${state.theme==='light'?'chosen':''}">☀️<b>Светлая</b></button><button data-theme="dark" class="${state.theme==='dark'?'chosen':''}">🌙<b>Тёмная</b></button></div><h3>Фон чата</h3><div class="wallpapers"><button>🌌</button><button>🌿</button><button>☁️</button><button>🌅</button><button>◼️</button></div></div>`}
  async function handleAction(a,id){try{if(a==='logout'){await api('/auth/logout',{method:'POST'});localStorage.removeItem('fenix_token');state.token='';closeDrawer();render();return}if(a==='toggle-theme'){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('fenix_theme',state.theme);await api('/social/settings',{method:'PATCH',body:JSON.stringify({theme:state.theme})}).catch(()=>{});closeDrawer();render();return}if(a==='profile'){closeDrawer();openDrawer('profile');return}if(a==='settings'){closeDrawer();openDrawer('settings');return}if(a==='appearance'){closeDrawer();openDrawer('appearance');return}if(a==='contacts'){closeDrawer();openDrawer('contacts');setTimeout(bindPeople,50);return}if(a==='calls'||a==='devices'){closeDrawer();openDrawer(a);return}if(a==='saved'){const c=await api('/chats/saved');if(!state.chats.some(x=>x.id===c.id))state.chats.unshift(c);closeDrawer();openChat(c.id);return}if(a==='reply'){state.reply=state.messages.find(x=>x.id===Number(id));closeDrawer();renderChat();$('#message-input')?.focus();return}if(a==='favorite'){await api(`/extras/favorites/${id}`,{method:'POST'});toast('Добавлено в Избранное');closeDrawer();return}if(a==='pin'){await api(`/chats/${state.chat.id}/messages/${id}/pin`,{method:'POST'});toast('Статус закрепления изменён');closeDrawer();return}if(a==='reaction'){await api(`/chats/${state.chat.id}/messages/${id}/reaction`,{method:'POST',body:JSON.stringify({emoji:'❤️'})});toast('❤️');closeDrawer();return}if(a==='delete'){await api(`/chats/${state.chat.id}/messages/${id}`,{method:'DELETE'});state.messages=state.messages.map(x=>x.id===Number(id)?{...x,deleted:true,text:''}:x);closeDrawer();renderChat();return}if(a==='edit'){const m=state.messages.find(x=>x.id===Number(id));const n=prompt('Изменить сообщение',m?.text||'');if(n!==null){await api(`/chats/${state.chat.id}/messages/${id}`,{method:'PATCH',body:JSON.stringify({text:n})});state.messages=await api(`/chats/${state.chat.id}/messages?limit=200`);closeDrawer();renderChat()}return}if(a==='edit-profile'){toast('Профиль: редактирование подключим к форме настроек');closeDrawer();return}}catch(e){toast(e.message)}}
  function bindPeople(){const q=$('#people-q'),go=$('#people-go');if(!q)return;const run=async()=>{const v=q.value.trim();if(v.length<2)return toast('Минимум 2 символа');try{const arr=await api('/social/people?q='+encodeURIComponent(v));$('#people-list').innerHTML=arr.length?arr.map(u=>`<button class="person-row" data-uid="${u.id}">${avatar(u)}<span><b>${esc(u.display_name)}</b><small>@${esc(u.username)} · ID ${esc(u.public_code||u.id)}</small></span><i>›</i></button>`).join(''):'<div class="muted center">Пользователь не найден</div>';$$('.person-row').forEach(x=>x.onclick=async()=>{const c=await api('/chats/private',{method:'POST',body:JSON.stringify({other_user_id:Number(x.dataset.uid)})});if(!state.chats.some(z=>z.id===c.id))state.chats.unshift(c);closeDrawer();openChat(c.id)})}catch(e){toast(e.message)}};go.onclick=run;q.onkeydown=e=>{if(e.key==='Enter')run()}}
  render();if(state.token)boot();
})();
